mapper.select:
SELECT f.fund_code AS fundCode, f.fund_name AS fundName, f.fund_type AS fundType, f.risk_level AS riskLevel, f.establish_date AS establishDate, f.scale AS scale, fn.unit_nav AS latestNav, fn.nav_date AS latestNavDate, fn.daily_return AS dailyReturn FROM fund f LEFT JOIN fund_nav fn ON f.fund_code = fn.fund_code AND fn.deleted = 0 AND fn.nav_date = ( SELECT MAX(n2.nav_date) FROM fund_nav n2 WHERE n2.fund_code = f.fund_code AND n2.deleted = 0 ) WHERE f.deleted = 0 AND f.status = 1
AND (f.fund_code LIKE CONCAT('%', #{keyword}, '%') OR f.fund_name LIKE CONCAT('%', #{keyword}, '%'))
AND f.fund_type = #{fundType}
AND f.risk_level = #{riskLevel}
ORDER BY
fn.daily_return ASCDESC
f.scale ASCDESC
f.establish_date ASCDESC
fn.daily_return DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM fund f WHERE f.deleted = 0 AND f.status = 1
AND (f.fund_code LIKE CONCAT('%', #{keyword}, '%') OR f.fund_name LIKE CONCAT('%', #{keyword}, '%'))
AND f.fund_type = #{fundType}
AND f.risk_level = #{riskLevel}
